export async function createTextFile(input, api) {
  const saved = await api.artifacts.create({ name: input.name, mime: input.mime, text: input.text });
  if (!saved || saved.saved !== true || typeof saved.artifactId !== 'string' || !saved.artifactId) {
    throw new Error('artifact-not-confirmed');
  }
  return '文件已保存到本会话的“插件文件”，可以在那里查看或另存。';
}

export async function proposeFileChange(input, api) {
  let baseHash = null;
  if (!input.new_file) {
    const existing = await api.workspace.readText({ path: input.path, maxBytes: 131072 });
    if (!existing || typeof existing.sha256 !== 'string' || !/^[a-f0-9]{64}$/.test(existing.sha256)) {
      throw new Error('file-hash-not-confirmed');
    }
    baseHash = existing.sha256;
  }
  const proposed = await api.workspace.proposePatch({ path: input.path, baseHash, content: input.content });
  if (!proposed || proposed.status !== 'pending' || typeof proposed.proposalId !== 'string' || !proposed.proposalId) {
    throw new Error('proposal-not-confirmed');
  }
  return '修改提案已创建，项目文件尚未改动。到“插件文件”检查差分后再应用；应用遵守当前权限。';
}
